package com.travbook.railtickets.adapter.in.web;
import com.travbook.railtickets.domain.model.RailTicket.*;
import com.travbook.railtickets.domain.model.RailTicket;
import com.travbook.railtickets.application.port.in.RailTickets.*;
import com.travbook.rail.domain.model.Rail.*;
import java.time.*;
import java.util.*;
final class RailTicketViews {
    record MoneyView(String amount,String currency){static MoneyView of(Money m){return new MoneyView(m.amount().toPlainString(),m.currency());}}
    record AvailabilityView(TravelClass travelClass,Quota quota,com.travbook.rail.domain.model.Rail.Status status,int position,MoneyView base,MoneyView fees,MoneyView total,String fareBasis,Instant observedAt,Instant validUntil,Instant quotaOpensAt,List<String> restrictions){static AvailabilityView of(Availability a){return new AvailabilityView(a.travelClass(),a.quota(),a.status(),a.position(),MoneyView.of(a.base()),MoneyView.of(a.fees()),MoneyView.of(a.total()),"ONE_ADULT_DEMONSTRATION",a.observedAt(),a.validUntil(),a.quotaOpensAt(),a.restrictions());}}
    record JourneyView(UUID id,String supplier,String number,String name,Station origin,Station destination,OffsetDateTime departure,OffsetDateTime arrival,int durationMinutes,List<DayOfWeek> operatingDays,List<Stop> route,List<AvailabilityView> availability){static JourneyView of(Journey j){return new JourneyView(j.id(),j.supplier(),j.number(),j.name(),j.origin(),j.destination(),j.departure(),j.arrival(),j.durationMinutes(),j.operatingDays(),j.route(),j.availability().stream().map(a->AvailabilityView.of(a)).toList());}}

 record QuoteView(UUID id,int version,String mode,JourneyView journey,AvailabilityView availability,String boardingStation,List<Passenger> passengers,String policy,String cancellationPolicy,MoneyView previousTotal,MoneyView total,Instant createdAt,Instant expiresAt,Instant acceptedAt,boolean expired,UUID bookingId){static QuoteView of(QuoteDetails d){var q=d.quote();var s=q.selection();return new QuoteView(q.id(),q.version(),"MOCK",JourneyView.of(s.journey()),AvailabilityView.of(s.availability()),s.boardingStation(),s.passengers(),s.policy(),RailTicket.CANCELLATION,MoneyView.of(s.previousTotal()),MoneyView.of(s.total()),q.createdAt(),q.effectiveExpiry(),d.acceptedAt(),d.expired(),d.bookingId());}}
 record BookingView(UUID id,String mode,QuoteView quote,Scenario scenario,long version,Instant createdAt,Instant updatedAt,RailTicket.Status status,Payment payment,Reservation reservation,Refund refund,Step step,String supplierReference,String paymentReference,String refundReference,String failureCode,MoneyView refundAmount,boolean terminal){static BookingView of(Booking b,Instant now){return new BookingView(b.id(),"MOCK",QuoteView.of(new QuoteDetails(b.quote(),b.acceptedAt(),b.id(),b.quote().expired(now))),b.scenario(),b.version(),b.createdAt(),b.updatedAt(),b.status(),b.payment(),b.reservation(),b.refund(),b.step(),b.supplierReference(),b.paymentReference(),b.refundReference(),b.failureCode(),MoneyView.of(b.cancellation()==null?Money.inr(java.math.BigDecimal.ZERO):b.cancellation().quote().refundAmount()),b.terminal());}}
 record Summary(UUID id,String trainName,OffsetDateTime departure,String mode,RailTicket.Status status,Payment payment,Reservation reservation,Refund refund,MoneyView total,Instant createdAt){static Summary of(Booking b){return new Summary(b.id(),b.quote().selection().journey().name(),b.quote().selection().journey().departure(),"MOCK",b.status(),b.payment(),b.reservation(),b.refund(),MoneyView.of(b.quote().selection().total()),b.createdAt());}}
 record ListView(List<Summary> items,UUID nextCursor){}
 record CancellationView(UUID id,UUID bookingId,long bookingVersion,MoneyView refundAmount,MoneyView retainedAmount,Instant createdAt,Instant expiresAt,String mode){static CancellationView of(CancellationQuote q){return new CancellationView(q.id(),q.bookingId(),q.bookingVersion(),MoneyView.of(q.refundAmount()),MoneyView.of(q.retainedAmount()),q.createdAt(),q.expiresAt(),"MOCK");}}
 record VoucherView(UUID id,UUID bookingId,String kind,String mode,Instant createdAt,String sha256,int byteLength,String downloadUrl){static VoucherView of(Voucher v){return new VoucherView(v.id(),v.bookingId(),"MOCK_RAIL_TICKET_SUMMARY","MOCK",v.createdAt(),v.sha256(),v.byteLength(),"/api/v1/rail-ticket-bookings/"+v.bookingId()+"/voucher/content");}}
 record EventView(UUID eventId,String eventType,long aggregateVersion,Instant occurredAt,String mode,String status,String payment,String reservation,String refund){static EventView of(Event e){return new EventView(e.eventId(),e.eventType(),e.aggregateVersion(),e.occurredAt(),"MOCK",e.status(),e.payment(),e.reservation(),e.refund());}}
 record BookingV2(UUID id,String mode,QuoteView quote,Scenario scenario,long version,Instant createdAt,Instant updatedAt,RailTicket.Status status,Payment payment,Reservation reservation,Refund refund,Step step,String supplierReference,String paymentReference,String refundReference,String failureCode,MoneyView refundAmount,boolean terminal,List<Integer> cancelledPassengerIndexes,List<Integer> latestCancellationPassengerIndexes,List<CancellationResultView> cancellations,MoneyView refundedTotal){static BookingV2 of(Booking b,Instant now,List<CancellationResult> history){return new BookingV2(b.id(),"MOCK",QuoteView.of(new QuoteDetails(b.quote(),b.acceptedAt(),b.id(),b.quote().expired(now))),b.scenario(),b.version(),b.createdAt(),b.updatedAt(),b.status(),b.payment(),b.reservation(),b.refund(),b.step(),b.supplierReference(),b.paymentReference(),b.refundReference(),b.failureCode(),MoneyView.of(b.cancellation()==null?Money.inr(java.math.BigDecimal.ZERO):b.cancellation().quote().refundAmount()),b.terminal(),b.cancelledPassengerIndexes(),b.cancellationScope(),history.stream().map(CancellationResultView::of).toList(),MoneyView.of(Money.inr(history.stream().filter(r->r.status()==Refund.SUCCEEDED).map(r->r.refundAmount().amount()).reduce(java.math.BigDecimal.ZERO,(sum,amount)->sum.add(amount)))));}}
 record CancellationResultView(UUID quoteId,List<Integer> passengerIndexes,MoneyView refundAmount,Refund status,String reference,Instant completedAt){static CancellationResultView of(CancellationResult r){return new CancellationResultView(r.quoteId(),r.passengerIndexes(),MoneyView.of(r.refundAmount()),r.status(),r.reference(),r.completedAt());}}
 record PassengerCancellationView(UUID id,UUID bookingId,long bookingVersion,MoneyView refundAmount,MoneyView retainedAmount,Instant createdAt,Instant expiresAt,String mode,List<Integer> passengerIndexes,String policy){static PassengerCancellationView of(CancellationQuote q){return new PassengerCancellationView(q.id(),q.bookingId(),q.bookingVersion(),MoneyView.of(q.refundAmount()),MoneyView.of(q.retainedAmount()),q.createdAt(),q.expiresAt(),"MOCK",q.passengerIndexes(),q.policy());}}
}
